from .parser import Binding, parse_stream
from .variables import parse_variables

logger = logging.getLogger(__name__)

if IS_TYPE_CHECKING:
    from typing import (IO, Dict, Iterable, Iterator, Mapping, Optional, Text,
                        Tuple, Union)
    if sys.version_info >= (3, 6):
